WITH latest AS (SELECT *, ROW_NUMBER() OVER (PARTITION BY promo_code ORDER BY ends_on DESC, id) AS dedup_rank FROM promotions QUALIFY dedup_rank = 1) SELECT DATE_TRUNC('YEAR', starts_on) AS year_start, DATE_TRUNC('QUARTER', starts_on) AS quarter_start, COUNT(CASE WHEN promo_code = 'BUNDLE' THEN 1 END) AS bundle_count, COUNT(*) AS row_count, SORT_ARRAY(COLLECT_SET(channel)) AS channel_list, SORT_ARRAY(COLLECT_SET(channel)) AS channel_list_2, DENSE_RANK() OVER (PARTITION BY DATE_TRUNC('YEAR', starts_on) ORDER BY COUNT(*) DESC) AS row_count_dense_rank FROM latest GROUP BY DATE_TRUNC('YEAR', starts_on), DATE_TRUNC('QUARTER', starts_on) ORDER BY bundle_count DESC NULLS FIRST
